    "author": "樊曦,苏凯洋,张斌,王自宸,王松",
    "description": "新华社北京9月25日电 题：四条高铁将开通 全国高铁网络多点扩容提质增效 新华社记者 金秋时节，一批重点高铁线路即将开通运营。记者25日从中国国家铁路集团有限公司获悉，9月28日，京港高铁雄安至商丘段、西渝高铁西安至安康段、宜昌至兴山高铁、哈尔滨至伊春高铁将集中亮相。 四条新线穿越华北、西北、华中、东北，将进一步织密“八纵八横”高速铁路网，压缩区域时空距离，便利沿线群众出行，为区域高质量发展注入交通新动能。 “目前，四条线路均已完成联调…",
    "content": "新华社北京9月25日电 题：四条高铁将开通 全国高铁网络多点扩容提质增效 新华社记者 金秋时节，一批重点高铁线路即将开通运营。记者25日从中国国家铁路集团有限公司获悉，9月28日，京港高铁雄安至商丘段、西渝高铁西安至安康段、宜昌至兴山高铁、哈尔滨至伊春高铁将集中亮相。 四条新线穿越华北、西北、华中、东北，将进一步织密“八纵八横”高速铁路网，压缩区域时空距离，便利沿线群众出行，为区域高质量发展注入交通新动能。 “目前，四条线路均已完成联调联试、检测验收和安全评估，轨道、通信信号、列车控制等各系统状态稳定，满足安全运营…"
