    "content": "开市客披露年度开店计划。 9月24日，全球仓储式会员店运营商Costco（Nasdaq: COST，以下简称“开市客”）发布截至2026年8月30日的2026财年第四财季及全财年业绩。第四财季业绩超出市场预期，实现总营收达957.23亿美元，同比增长11.1%。其中，实现净销售额为938.73亿美元，同比增长11.2%；实现会员费收入18.5亿美元，同比增7.3%。实现净利润为29.98亿美元，同比增长14.9%。 2026财年，开市客实现总营收达3031.54亿美元，同比增长10.1%。其中，净销售额为2972.…"
