    "description": "新华社联合国9月24日电 通讯｜掌声与退席——巴以同日在联大辩论上发声 新华社记者高山 施春 刘亚南 24日，在纽约联合国总部举行的第81届联合国大会一般性辩论进入第三天。巴勒斯坦和以色列同日发声，却以截然不同的方式成为会场焦点。 由于美国再次拒绝发放签证，巴勒斯坦总统阿巴斯无法亲赴纽约，只能发表视频讲话，向国际社会痛陈一个民族正在经历的苦难。讲话结束后，会场响起热烈掌声，众多国家代表表达对巴勒斯坦人民的关注与支持。 发言中，阿巴斯以沉…",
    "content": "新华社联合国9月24日电 通讯｜掌声与退席——巴以同日在联大辩论上发声 新华社记者高山 施春 刘亚南 24日，在纽约联合国总部举行的第81届联合国大会一般性辩论进入第三天。巴勒斯坦和以色列同日发声，却以截然不同的方式成为会场焦点。 由于美国再次拒绝发放签证，巴勒斯坦总统阿巴斯无法亲赴纽约，只能发表视频讲话，向国际社会痛陈一个民族正在经历的苦难。讲话结束后，会场响起热烈掌声，众多国家代表表达对巴勒斯坦人民的关注与支持。 发言中，阿巴斯以沉重的语调说，巴勒斯坦人民正经历“历史上最危险的时期之一”，人道主义灾难在加沙地带…"
