    "author": "牛润哲,侯文坤",
    "description": "新华社武汉9月25日电（记者牛润哲、侯文坤）家猪的祖先——野猪究竟从哪里来？我国科研人员给出了新解答。崖州湾国家实验室、华中农业大学联合国内外多家科研机构发现，现代野猪并非如当前主流观点所言起源于东南亚岛屿，而是源自亚洲大陆的热带地区，其中南亚及喜马拉雅区系可能是其重要演化源头。相关研究成果于北京时间9月25日凌晨在线发表于国际学术期刊《科学》。 “猪的遗传规律与种质资源在起源与驯化中逐步形成，相关研究可为种猪遗传改良提供理论和技术支撑…",
    "content": "新华社武汉9月25日电（记者牛润哲、侯文坤）家猪的祖先——野猪究竟从哪里来？我国科研人员给出了新解答。崖州湾国家实验室、华中农业大学联合国内外多家科研机构发现，现代野猪并非如当前主流观点所言起源于东南亚岛屿，而是源自亚洲大陆的热带地区，其中南亚及喜马拉雅区系可能是其重要演化源头。相关研究成果于北京时间9月25日凌晨在线发表于国际学术期刊《科学》。 “猪的遗传规律与种质资源在起源与驯化中逐步形成，相关研究可为种猪遗传改良提供理论和技术支撑。”论文共同通信作者、中国工程院院士赵书红说。然而，受限于南亚地区基因组数据的长…"
