    "content": "新华社耶路撒冷9月25日电（记者庞昕熠 王卓伦）据《以色列时报》网站报道，两名以军士兵24日下午在加沙地带操作一架小型军用无人机时，无人机因不明原因坠毁。随后，无人机在被两人捡起时发生爆炸，导致两人身亡。 以色列国防军25日发表声明证实，两名以军预备役士兵24日在加沙地带北部死亡。 据以色列公共广播公司报道，这架无人机属于“阿塔莱夫”系列，可用作自杀式无人机，也被用于携带和投放炸弹。以军称，此次坠毁并非由巴勒斯坦伊斯兰抵抗运动（哈马斯）的电子战或信号干扰所致。 “阿塔莱夫”系列无人机是2023年10月哈马斯突袭以色…"
