    "description": "中秋佳节，全球共庆。近日，海外多地中秋晚会精彩上演。从《小河淌水》到《彩云追月》，再到《月亮代表我的心》……中外友人用不同语言唱响关于“月亮”的旋律，寄托对团圆的美好祝愿。同一轮明月下，纵隔万里亦如咫尺。四海皆兄弟，月圆人团圆。 编导：李俞辉、黎淑同 记者：吴长伟、易爱军、张敬尧、熊文苑、刘颍、陈怡 摄像：万坡、孟韬、谭耀明、祖尔、金颢旼 新华社音视频部制作",
