    "author": "“中国海警”微信公号",
    "description": "中国海警局新闻发言人姜略表示，9月24日，菲律宾背信违约，不顾中方劝告，一意孤行派出运补船为非法“坐滩”仁爱礁船只运补。中国海警依法对菲运补船采取现场跟监、喊话警告等措施。菲方在中方节日期间采取挑衅行径并煽宣炒作，严重违反《南海各方行为宣言》，严重破坏南海地区和平稳定。我们正告菲方立即停止挑衅滋事，中国海警将依法在包括仁爱礁在内的南沙群岛及其附近海域开展维权执法活动，坚决维护国家领土主权和海洋权益。",
