    "content": "快科技9月25日消息，日前，由多位知名电商主播带货、销量上万单的网红“溜溜凳”被曝内部使用的竟是废弃材料。 有消费者在社交媒体发布拆解视频，称其在交个朋友直播间购买的一款“万向轮溜溜凳”存在严重质量问题，凳子内部使用的是发霉木板和废旧海绵等来路不明的废弃材料。 据其介绍，这款凳子购自店铺“交个朋友智能家居爆品榜”，实付价格89.9元，拆开后不仅发现内部材料质量低劣，产品还长期散发出异味。 此事引发网络关注和热议，今日上午，“交个朋友直播间”官方账号就此事进行回应并致歉： 近日，有消费者反映交个朋友直播间销售的万向轮…"
