    "description": "新华社武汉9月25日电（记者牛润哲、张阳）9月25日，农历八月十五，中秋佳节如约而至。今年恰逢干支纪年中60年一轮回的丙午年，民间俗称“赤马年”。一时间“‘赤马中秋’罕见”“‘赤马中秋’影响运势”等说法在网络流传。今年中秋到底有啥“不一样”？听专家为你解读。 从历法角度解释，所谓“赤马”，并不是真的有什么特殊的“红色马”，而是对丙午年的一种传统称谓，源于中国传统的干支纪年法。 干支纪年法以天干搭配地支按顺序两两组合，形成六十甲子。60年…",
    "content": "新华社武汉9月25日电（记者牛润哲、张阳）9月25日，农历八月十五，中秋佳节如约而至。今年恰逢干支纪年中60年一轮回的丙午年，民间俗称“赤马年”。一时间“‘赤马中秋’罕见”“‘赤马中秋’影响运势”等说法在网络流传。今年中秋到底有啥“不一样”？听专家为你解读。 从历法角度解释，所谓“赤马”，并不是真的有什么特殊的“红色马”，而是对丙午年的一种传统称谓，源于中国传统的干支纪年法。 干支纪年法以天干搭配地支按顺序两两组合，形成六十甲子。60年一个循环，从甲子始，至癸亥终。民俗学家、华东师范大学教授仲富兰告诉记者，今年正值…"
