    "content": "新华社杭州9月25日电 题：多项“首发首秀”亮相第五届数贸会 新华社记者许舜达、戴锦镕 23日至27日，由浙江省人民政府、商务部共同主办的第五届全球数字贸易博览会在浙江杭州举行。本届数贸会以“在数贸会遇见AI未来”为年度主题，展览面积达17万平方米，参展企业超2000家，来自163个国家和地区的超5万名专业客商报名参会。从量子计算到太空算力，从AI智能体到智能穿戴，一批国内外首发、首秀、首展的新技术、新产品、新方案在展会现场集中亮相。 在数字贸易主题展馆，国内首台全栈式集成化大规模中性原子量子计算机亮相，杭州原子矩…"
