    "title": "江阴靖江长江隧道及南北接线正式通车",
    "link": "http://www.news.cn/20260925/1f45bc4bed774235a02725d47cf91195/c.html",
    "pub_date": "2026-09-25 15:14:28",
    "author": "许丛军（摄制）,黄培锋",
    "description": "9月24日，江阴靖江长江隧道及南北接线正式通车运营。该隧道是国家重点过江通道工程，全长约11.8公里，过江隧道段约6.4公里，全线按双向六车道高速公路标准建设。自此，G2京沪高速大通道江苏段正式形成“一桥一隧”双向十二车道的全新过江格局，将显著提升京沪高速江苏段整体通行能力。 摄制：许丛军 新华社音视频部制作",
