    "content": "近日，中国插花花艺协会、中国花卉协会联合发出通知称，为严格落实《社会组织评比表彰活动管理办法》相关规定，规范行业评比表彰工作秩序，经中国插花花艺协会、中国花卉协会研究决定，撤销两家协会于2006年共同评选的“中国插花花艺资深大师”(4名)、“中国插花花艺大师”(9名)称号。 通知强调，此前所颁证书即刻失效，原评选配套文件同步废止。任何单位、个人不得以任何形式使用“大师”名义开展宣传、推介活动。 中国插花花艺协会是由中国插花花艺界的教学、科研、经营管理单位、插花花艺家自愿结成的全国性、行业性社会团体。公开报道显示，2…"
