    "author": "李明睿",
    "description": "新华社北京9月25日电 德国安联集团24日发布的研究报告显示，今年夏季热浪预计给德国造成约250亿欧元经济损失。 报告说，由于缺乏空调等降温设备，高温使员工休息时间延长、缺勤率增加，导致德国生产力下降。受热浪影响，德国今年经济增速降低约0.54个百分点，损失约占全年国内生产总值的0.53%。 这是7月30日在德国柏林主火车站拍摄的高温警示显示屏。新华社记者张豪夫摄 今年6月下旬，德国气温连续三天打破历史纪录，最高气温一度超过42摄氏度。…",
