    "title": "根植大陆数十载 三台商上海再创业",
    "link": "http://www.news.cn/20260925/959f5f0ecc04455cbadf455917e33b7a/c.html",
    "pub_date": "2026-09-25 14:40:18",
    "author": "潘清",
    "description": "新华社上海9月25日电（记者潘清）今年中秋，除了与家人朋友团聚，76岁的台商苏扬修还多了一项日程，到开业不久的贝比食代九亭店，看看哪些面包品种最受欢迎，听听消费者有什么意见和建议。 开设在上海闵行区的这个门店面积不大，装修也不算华丽。来来往往的人流里，藏着一段三位台商“224岁”再出发的创业故事。 苏扬修早年是台湾知名造型师，曾在《粉红女郎》《家有仙妻》等热播电视剧中担纲造型总监。上世纪90年代，苏扬修随台商“登陆潮”来大陆发展，现任上…",
