    "pub_date": "2026-09-25 14:18:58",
    "author": "corerice",
    "description": "在我的项目里有个叫 Card 的产品，其中有一套我很在意的能力：AI 给出的候选答案，不能直接当成事实，还需要根据证据重新判断哪些内容值得相信。 这套能力后来逐渐独立成了 CEE｜Card Evidence Engine，一个本地优先的证据判断引擎。 在 Benchmark v2 中，CEE 在强制断网环境下完成判断，p50 为 68.55 ms；32 项固定契约测试全部通过，正常环境与离线环境的判断差异为 0。本轮共完成 9,600 …",
    "content": "在我的项目里有个叫 Card 的产品，其中有一套我很在意的能力：AI 给出的候选答案，不能直接当成事实，还需要根据证据重新判断哪些内容值得相信。 这套能力后来逐渐独立成了 CEE｜Card Evidence Engine，一个本地优先的证据判断引擎。 在 Benchmark v2 中，CEE 在强制断网环境下完成判断，p50 为 68.55 ms；32 项固定契约测试全部通过，正常环境与离线环境的判断差异为 0。本轮共完成 9,600 次正常环境测量，也覆盖了冲突识别、证据不足、错误确定等情况。 这次算是我第一次正…"
