    "content": "htmx 团队发布了 htmx 4.0.0 \"。这是继 2024 年 htmx 2.0 发布以来，该超媒体库的首个主版本更新。新版本历经八个月开发，直接跳过了 3.0 版本。htmx 创始人 Carson Gross 曾承诺永远不会有 htmx 3.0。当 InfoWorld 问及此次版本跨越时，他用 一个词概括了这一变化 \"：“Oops”（哎呀）。 htmx 已将长期使用的 XMLHttpRequest 传输机制替换为现代 fetch() API。这次重写支持原生流式传输，同时将脚本体积控制在约 14KB。对大多…"
