    "content": "■到对岸就是胜利 湘江秋水北去，桂北群山如黛。 关乎中央红军生死存亡的湘江战役，主要在湘江上游的广西全州、兴安、灌阳三个县打响。1934年底，为确保中共中央和中央红军主力渡江，粉碎敌人围歼红军于湘江以东的企图，几万名红军将士凭借着“到对岸就是胜利”的信念，冒死强渡湘江。 在湘江界首渡口，群众帮助红军用小船和木板搭建浮桥，红军主力凭靠浮桥抢渡湘江。搭桥时木板不够用，红军借用当地群众家的门板，并给每个门板都写上编号，以便赔偿。 湘江战役中，红军以巨大的牺牲突破了封锁，赢得了战略胜利。湘江战役引发了党对于革命路线的深刻反…"
